INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1013, 'math', 'g3', 'apply', 2, '{"stem":"妈妈带了 300 元去买东西，买裤子用了 84 元，买上衣用了 116 元，妈妈还剩下多少元？（用两种方法解答）"}', '100 元', '方法一：300-(84+116)=300-200=100（元）; 方法二：300-84-116=216-116=100（元）', 'jsj3_sx_v95', '["jsj3_sx","U1","p010","阶段练2","apply_01"]', 1, NULL);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1013, 'math', 'g3', 'apply', 2, '{"stem":"儿童节时小明和爸爸、妈妈一起到\"水上乐园\"游玩，他们一家买门票要付多少元？（水上乐园票价：成人 60 元/位，儿童 40 元/位；儿童节儿童半价）"}', '140 元', '爸爸、妈妈成人 60×2=120（元），小明儿童半价 40÷2=20（元），共 120+20=140（元）', 'jsj3_sx_v95', '["jsj3_sx","U1","p010","阶段练2","apply_02"]', 1, NULL);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1010, 'math', 'g3', 'apply', 2, '{"stem":"一个足球 98 元，6 个皮球 54 元，一个足球比一个皮球贵多少元？"}', '89 元', '一个皮球 54÷6=9（元），98-9=89（元）', 'jsj3_sx_v95', '["jsj3_sx","U1","p010","阶段练2","apply_03"]', 1, NULL);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1010, 'math', 'g3', 'apply', 3, '{"stem":"从公园到东东家有 350 米，从学校到东东家有多少米？（图示：公园--350米--东东家--630米--超市--320米--学校）"}', '600 米', '学校到超市 320 米，超市到东东家 630 米，公园到东东家 350 米；学校到东东家 = 320+630-350=600（米）', 'jsj3_sx_v95', '["jsj3_sx","U1","p011","阶段练2","apply_04"]', 1, NULL);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1013, 'math', 'g3', 'apply', 3, '{"stem":"商场搞促销活动，购物满 1000 元减 158 元。张叔叔想买一辆自行车（549 元）、一台电风扇（239 元）和一个电水壶（229 元），带 900 元够吗？"}', '够，付 859 元', '549+239+229=1017（元），1017>1000 减 158，实际付 1017-158=859（元），900>859，够', 'jsj3_sx_v95', '["jsj3_sx","U1","p011","阶段练2","apply_05"]', 1, NULL);
INSERT INTO questions (node_id, subject, grade, type, difficulty, content, answer, analysis, source, tags, reviewed, images) VALUES (1013, 'math', 'g3', 'apply', 3, '{"stem":"每 3 个空瓶可以换一瓶汽水，同学们买了 27 瓶汽水，喝完后又用空瓶换汽水，那么，同学们最后一共可喝到多少瓶汽水？（写出过程）"}', '40 瓶', '27÷3=9（瓶）; 9÷3=3（瓶）; 3÷3=1（瓶）; 共 27+9+3+1=40（瓶）', 'jsj3_sx_v95', '["jsj3_sx","U1","p011","阶段练2","think_01"]', 1, NULL);
